import type { Question } from '../../lib/types'
export const rds_aurora_questions: Question[] = [
  { id: 'd2-rds-001', domain: 2, topics: ['RDS', 'Multi-AZ', 'failover'], type: 'single', stem: 'An RDS MySQL instance has Multi-AZ enabled. The primary instance fails. What happens?', options: [{ id: 'A', text: 'A read replica is promoted — requires manual intervention in the RDS console' }, { id: 'B', text: 'Automatic failover to the standby in a different AZ; DNS CNAME updates within ~1-2 minutes' }, { id: 'C', text: 'The primary instance restarts in the same AZ — Multi-AZ provides restartability, not failover' }, { id: 'D', text: 'AWS Support must be notified to initiate failover — it does not happen automatically' }], correct: ['B'], explanation: 'RDS Multi-AZ: a synchronous standby replica in another AZ. On failure, RDS automatically updates the DNS CNAME from primary to standby — typically within 1-2 minutes. No manual intervention required.', distractors: { A: 'Read replicas are for read scaling — Multi-AZ uses a dedicated standby that is promoted automatically.', C: 'Multi-AZ provides AZ-level failover — it is not just restartability within the same AZ.', D: 'Multi-AZ failover is fully automatic — AWS Support involvement is not required.' } },
  { id: 'd2-rds-002', domain: 2, topics: ['RDS', 'read replicas'], type: 'single', stem: 'An RDS instance is overwhelmed by read queries. What provides horizontal read scaling?', options: [{ id: 'A', text: 'Multi-AZ deployment — routes read queries to the standby automatically' }, { id: 'B', text: 'RDS Read Replicas — asynchronous replicas that serve read traffic on a separate endpoint' }, { id: 'C', text: 'Increase instance size — vertical scaling handles increased read query volume' }, { id: 'D', text: 'Enable Enhanced Monitoring — identifies and optimizes slow read queries automatically' }], correct: ['B'], explanation: 'Read Replicas use asynchronous replication to provide additional read capacity. Applications read from the replica endpoint, relieving the primary. Up to 15 replicas for Aurora, 5 for MySQL/PostgreSQL.', distractors: { A: 'Multi-AZ standby does not serve reads — it is for failover only. Aurora Multi-AZ reader nodes do serve reads.', C: 'Vertical scaling (resize) has limits and requires downtime for RDS — horizontal scaling with replicas is more flexible.', D: 'Enhanced Monitoring provides metrics — it does not optimize queries or provide read scaling.' } },
  { id: 'd2-rds-003', domain: 2, topics: ['RDS', 'encryption', 'KMS'], type: 'single', stem: 'An existing unencrypted RDS instance must be encrypted. How?', options: [{ id: 'A', text: 'Enable encryption in the RDS console — encryption is applied online without downtime' }, { id: 'B', text: 'Take a snapshot of the unencrypted instance, copy the snapshot with encryption enabled, restore from the encrypted snapshot' }, { id: 'C', text: 'Enable AWS Macie on the RDS instance — it automatically encrypts unencrypted databases' }, { id: 'D', text: 'Encryption can only be enabled at creation — unencrypted databases must be re-created' }], correct: ['B'], explanation: 'RDS encryption cannot be enabled on a running instance. Workflow: create a snapshot → copy snapshot with encryption (specify KMS key) → restore from encrypted snapshot → update connection strings.', distractors: { A: 'Online encryption toggle does not exist for RDS — the snapshot-copy-restore workflow is required.', C: 'Macie is a data classification service — it does not encrypt databases.', D: 'Encryption can be added via the snapshot workflow — it is not true that only new instances can be encrypted.' } },
  { id: 'd2-rds-004', domain: 2, topics: ['RDS', 'automated backups', 'retention'], type: 'single', stem: 'An RDS database must be recoverable to any point in the last 14 days. Configuration?', options: [{ id: 'A', text: 'Enable automated backups with a 14-day retention period (max is 35 days)' }, { id: 'B', text: 'Create manual snapshots daily — automatic backups have a maximum 7-day retention' }, { id: 'C', text: 'Enable AWS Backup with a 14-day vault retention policy' }, { id: 'D', text: 'Both A and C — automated backups and AWS Backup both support 14-day retention' }], correct: ['A'], explanation: 'RDS automated backups: configurable retention of 1–35 days. Enable automated backups with 14-day retention. PITR (point-in-time recovery) is available within the retention window.', distractors: { B: 'Automated backups support up to 35 days — 7 days is the minimum meaningful retention, not the maximum.', C: 'AWS Backup can manage RDS backups — but RDS automated backups with 14-day retention achieves PITR natively without AWS Backup.', D: 'Automated backups alone (answer A) achieve the goal — AWS Backup is optional additional management.' } },
  { id: 'd2-rds-005', domain: 2, topics: ['RDS', 'storage autoscaling'], type: 'single', stem: 'An RDS instance storage is filling up. How to prevent running out of space without manual intervention?', options: [{ id: 'A', text: 'Increase the storage allocation in the RDS console — RDS resizes online without downtime' }, { id: 'B', text: 'Enable RDS Storage Autoscaling with a maximum storage threshold — RDS expands storage automatically' }, { id: 'C', text: 'Use Aurora instead — Aurora storage scales to 128 TB automatically without configuration' }, { id: 'D', text: 'Create a CloudWatch alarm on FreeStorageSpace and manually resize when it triggers' }], correct: ['B'], explanation: 'RDS Storage Autoscaling: when free space drops below 10% for 5+ minutes AND storage has not scaled in the last 6 hours, RDS automatically expands storage up to the configured maximum. Zero intervention needed.', distractors: { A: 'Manual console resize works but requires human intervention — autoscaling eliminates this.', C: 'Aurora\'s auto-scaling storage is separate — RDS (non-Aurora) also has autoscaling via the setting in answer B.', D: 'CloudWatch alarm is a reactive notification — Storage Autoscaling is proactive expansion without a manual resize step.' } },
  { id: 'd2-rds-006', domain: 2, topics: ['RDS', 'IAM authentication'], type: 'single', stem: 'A Lambda function connects to RDS MySQL without storing database passwords. Solution?', options: [{ id: 'A', text: 'Store the password in AWS Secrets Manager and retrieve it at runtime using Lambda IAM role' }, { id: 'B', text: 'Enable RDS IAM database authentication — Lambda uses an IAM token instead of a password' }, { id: 'C', text: 'Use AWS SCT to generate database-specific tokens for Lambda connection' }, { id: 'D', text: 'Both A and B — Secrets Manager retrieval and IAM authentication are both valid passwordless approaches' }], correct: ['D'], explanation: 'Both approaches eliminate hardcoded passwords: (1) IAM authentication generates short-lived tokens using IAM role — no password stored anywhere; (2) Secrets Manager stores and rotates the password, retrieved via IAM role.', distractors: { A: 'Secrets Manager is a valid approach but incomplete — IAM authentication is also a valid passwordless method.', B: 'IAM authentication is correct but incomplete — Secrets Manager is also a valid approach.', C: 'AWS SCT (Schema Conversion Tool) is for database migration schema conversion — not for Lambda authentication.' } },
  { id: 'd2-rds-007', domain: 2, topics: ['RDS', 'parameter groups'], type: 'single', stem: 'A DBA needs to change the innodb_buffer_pool_size parameter. Current instance uses default parameter group. How?', options: [{ id: 'A', text: 'Modify the default parameter group directly — default groups are editable' }, { id: 'B', text: 'Create a custom parameter group, set the parameter value, associate with the instance' }, { id: 'C', text: 'SSH to the RDS instance and edit the my.cnf file directly' }, { id: 'D', text: 'The parameter can only be changed by recreating the instance with the correct setting' }], correct: ['B'], explanation: 'Default parameter groups cannot be modified. Create a custom parameter group, set the desired parameters, and associate it with the RDS instance. Some static parameters require a reboot to take effect.', distractors: { A: 'Default parameter groups are read-only — AWS does not allow modifying them.', C: 'There is no SSH access to RDS instances — it is a managed service with no OS-level access.', D: 'Parameter groups can be changed on existing instances — no recreation required for most parameters.' } },
  { id: 'd2-rds-008', domain: 2, topics: ['RDS', 'proxy'], type: 'single', stem: 'Lambda functions open many short-lived database connections, causing RDS connection pool exhaustion. Solution?', options: [{ id: 'A', text: 'Increase the max_connections parameter in RDS parameter group' }, { id: 'B', text: 'RDS Proxy — pools and multiplexes connections; Lambda connects to proxy, not directly to RDS' }, { id: 'C', text: 'Use DynamoDB instead of RDS for Lambda-connected workloads' }, { id: 'D', text: 'Configure Lambda connection limits to reduce concurrent invocations reaching RDS' }], correct: ['B'], explanation: 'RDS Proxy pools connections between Lambda and RDS. Many Lambda invocations share a smaller pool of actual database connections. Reduces connection overhead and protects RDS from connection storms.', distractors: { A: 'Increasing max_connections raises the limit but does not solve the connection churn problem from Lambda cold starts.', C: 'DynamoDB is a different service — RDS Proxy is the fix for RDS connection pool exhaustion.', D: 'Throttling Lambda reduces functionality — RDS Proxy is the purpose-built solution for this problem.' } },
  { id: 'd2-rds-009', domain: 2, topics: ['Aurora', 'storage', 'cluster volume'], type: 'single', stem: 'An Aurora cluster has 1 writer and 3 reader instances. How is storage shared between all four instances?', options: [{ id: 'A', text: 'Each instance has its own EBS volume with asynchronous replication to other instances' }, { id: 'B', text: 'All instances share a single cluster volume replicated across 6 copies in 3 AZs' }, { id: 'C', text: 'The writer has a primary volume; readers replicate from it with ~100ms lag' }, { id: 'D', text: 'Aurora uses a distributed S3 storage layer that all instances read from directly' }], correct: ['B'], explanation: 'Aurora\'s shared storage architecture: a single cluster volume with 6 copies across 3 AZs (2 per AZ). All instances (writer + readers) read from the same volume — no cross-instance replication lag for readers.', distractors: { A: 'Separate EBS volumes per instance would require replication — Aurora uses a shared cluster volume instead.', C: '100ms lag applies to traditional MySQL read replicas, not Aurora — Aurora readers see the same shared volume.', D: 'Aurora\'s storage is a specialized Aurora storage subsystem — not directly S3, though it is similar in architecture.' } },
  { id: 'd2-rds-010', domain: 2, topics: ['Aurora', 'endpoints'], type: 'single', stem: 'An application has both OLTP writes and heavy analytics reads. Aurora endpoint strategy?', options: [{ id: 'A', text: 'Single cluster endpoint — Aurora load-balances between writer and readers automatically' }, { id: 'B', text: 'Writer endpoint for writes; reader endpoint for read queries — automatically load-balances across all reader instances' }, { id: 'C', text: 'Custom endpoints — create separate custom endpoints for OLTP and analytics workloads' }, { id: 'D', text: 'Instance endpoints — connect directly to the specific instance for each workload type' }], correct: ['B'], explanation: 'Aurora reader endpoint: single DNS endpoint that load-balances across all available reader instances. Writer endpoint connects to the primary. Separating workloads prevents analytics reads from affecting write performance.', distractors: { A: 'The cluster endpoint routes to the writer only — it does not load-balance to readers.', C: 'Custom endpoints are for workload-specific instance groups (e.g., analytics on large instances) — reader endpoint is simpler for general read balancing.', D: 'Instance endpoints bypass load balancing — use reader or custom endpoints for production workloads.' } },
  { id: 'd2-rds-011', domain: 2, topics: ['Aurora', 'Serverless', 'v2'], type: 'single', stem: 'A development database has unpredictable traffic including long idle periods and occasional spikes. Cost-effective option?', options: [{ id: 'A', text: 't3.micro RDS instance — smallest instance type with lowest hourly cost' }, { id: 'B', text: 'Aurora Serverless v2 — scales automatically from near-zero to peak; charges per ACU-second' }, { id: 'C', text: 'DynamoDB on-demand — serverless NoSQL with no idle charges' }, { id: 'D', text: 'Aurora provisioned with a stop schedule — stop overnight to eliminate idle costs' }], correct: ['B'], explanation: 'Aurora Serverless v2: scales from 0.5 ACU minimum (near-zero cost at idle) to 128+ ACUs instantly on spikes. Charges per ACU-second — much cheaper than provisioned instances for bursty or idle workloads.', distractors: { A: 't3.micro charges hourly regardless of activity — Aurora Serverless charges per second of actual usage.', C: 'DynamoDB is NoSQL — if the application requires relational SQL, it is not an equivalent alternative.', D: 'Aurora stop schedules have limitations — Serverless v2 is simpler and scales without manual start/stop.' } },
  { id: 'd2-rds-012', domain: 2, topics: ['Aurora', 'global database'], type: 'single', stem: 'A financial application requires sub-second RPO and 1-minute RTO if an entire AWS region fails. Database solution?', options: [{ id: 'A', text: 'RDS Multi-AZ with a cross-region read replica — failover to cross-region replica manually' }, { id: 'B', text: 'Aurora Global Database — replication to secondary region with <1-second RPO; 1-minute RTO' }, { id: 'C', text: 'DynamoDB Global Tables — multi-region active-active with sub-millisecond replication' }, { id: 'D', text: 'RDS cross-region snapshot copy with automated restore scripts' }], correct: ['B'], explanation: 'Aurora Global Database: dedicated infrastructure replicates to up to 5 secondary regions with <1-second lag. In a regional failure, promote the secondary region writer in about 1 minute. Meets both RPO and RTO requirements.', distractors: { A: 'Cross-region RDS read replica requires manual promotion (minutes to hours) — RTO is not 1 minute.', C: 'DynamoDB Global Tables is the right choice for NoSQL — Aurora Global Database is the relational SQL option.', D: 'Snapshot restore takes tens of minutes or hours — it does not meet 1-minute RTO requirements.' } },
  { id: 'd2-rds-013', domain: 2, topics: ['RDS', 'Multi-AZ', 'read replica cross-region'], type: 'single', stem: 'An RDS instance needs disaster recovery in a different AWS region. What provides read capability in the DR region while the primary is healthy?', options: [{ id: 'A', text: 'Multi-AZ — provides a standby in a different AZ in the same region' }, { id: 'B', text: 'Cross-region read replica — provides a readable replica in another region for DR and read offloading' }, { id: 'C', text: 'RDS snapshot copy — create snapshots hourly and copy to the DR region' }, { id: 'D', text: 'AWS Backup cross-region copy — creates continuous backups in the DR region' }], correct: ['B'], explanation: 'Cross-region read replicas: asynchronous replication to a different region. The DR region has a readable replica — useful for DR (can be promoted) and for serving regional read traffic during normal operations.', distractors: { A: 'Multi-AZ is same-region — it does not provide a cross-region DR replica.', C: 'Snapshot copies restore point-in-time data — they do not provide a continuously updated readable database.', D: 'AWS Backup cross-region copies create backup copies — not a live readable replica database.' } },
  { id: 'd2-rds-014', domain: 2, topics: ['RDS', 'maintenance window'], type: 'single', stem: 'RDS minor version upgrades should happen automatically during a low-traffic window. Configuration?', options: [{ id: 'A', text: 'Enable Auto Minor Version Upgrade and set the maintenance window to a low-traffic time period' }, { id: 'B', text: 'Enable AWS Systems Manager Patch Manager for RDS — it applies patches during maintenance windows' }, { id: 'C', text: 'Minor version upgrades are manual only — AWS cannot apply them automatically' }, { id: 'D', text: 'Configure a CloudWatch Events rule that applies RDS upgrades during the maintenance window' }], correct: ['A'], explanation: 'Enable Auto Minor Version Upgrade on the RDS instance. Set the maintenance window (day and time in UTC) to the lowest-traffic period. AWS applies available minor version upgrades during this window automatically.', distractors: { B: 'Systems Manager Patch Manager patches EC2 instances — not RDS managed instances.', C: 'Minor version upgrades can be applied automatically with the auto minor upgrade setting.', D: 'CloudWatch Events cannot trigger RDS version upgrades — the RDS maintenance window setting handles this.' } },
  { id: 'd2-rds-015', domain: 2, topics: ['Aurora', 'failover', 'reader promotion'], type: 'single', stem: 'An Aurora cluster has a writer and 3 readers. The writer instance fails. What determines which reader is promoted?', options: [{ id: 'A', text: 'The reader with the most recent data is always promoted — lag determines promotion order' }, { id: 'B', text: 'Aurora promotes the reader with the highest promotion tier (lowest priority number); ties broken by size' }, { id: 'C', text: 'The oldest running reader is promoted — longest running = most stable' }, { id: 'D', text: 'AWS randomly selects a reader for promotion — promotion order is non-deterministic' }], correct: ['B'], explanation: 'Aurora failover: promotes the reader with the highest priority (tier 0 is highest, tier 15 is lowest). If multiple readers have the same tier, Aurora promotes the largest instance size. Set tiers strategically.', distractors: { A: 'Replication lag is not the promotion criterion — Aurora readers share the same storage volume with no lag.', C: 'Instance age is not used in Aurora promotion logic — promotion tier is the explicit configuration.', D: 'Promotion is deterministic — tier and size determine the order, not random selection.' } },
  { id: 'd2-rds-016', domain: 2, topics: ['RDS', 'option groups'], type: 'single', stem: 'A DBA needs to enable SQL Server Transparent Data Encryption (TDE) on an RDS SQL Server instance. How?', options: [{ id: 'A', text: 'Enable encryption in the RDS console — transparent encryption is a standard option' }, { id: 'B', text: 'Add TDE to an Option Group and associate the Option Group with the RDS instance' }, { id: 'C', text: 'Apply TDE through a custom parameter group on the RDS SQL Server instance' }, { id: 'D', text: 'SQL Server TDE requires a self-managed SQL Server — it is not supported on RDS' }], correct: ['B'], explanation: 'RDS Option Groups add optional features to specific database engines. For SQL Server and Oracle, options like TDE, native backup/restore, and Secure Sockets are added via Option Groups (not Parameter Groups).', distractors: { A: 'RDS console encryption enables KMS-based storage encryption — SQL Server TDE is engine-level encryption configured via Option Groups.', C: 'Parameter Groups configure database engine parameters — Option Groups enable optional features like TDE.', D: 'SQL Server TDE is supported on RDS via Option Groups — a self-managed instance is not required.' } },
  { id: 'd2-rds-017', domain: 2, topics: ['Aurora', 'Backtrack'], type: 'single', stem: 'A developer accidentally drops a table in Aurora MySQL. How can they recover quickly without restoring from a full backup?', options: [{ id: 'A', text: 'Aurora PITR — restore to a specific time before the DROP statement with 1-second granularity' }, { id: 'B', text: 'Aurora Backtrack — rewinds the database to any point within the backtrack window in minutes' }, { id: 'C', text: 'Aurora Snapshot — restore from the most recent automated snapshot taken before the accident' }, { id: 'D', text: 'Aurora binlog — replay transactions from before the DROP to recover the dropped table' }], correct: ['B'], explanation: 'Aurora Backtrack: rewinds the in-place database to a specific point in time within the backtrack window (up to 72 hours). No need to restore to a new cluster — backtrack is faster and in-place.', distractors: { A: 'PITR restores to a new Aurora cluster — it is slower than Backtrack for quick in-place recovery.', C: 'Snapshot restore creates a new cluster — takes longer than Backtrack and requires connection string changes.', D: 'Binlog replay would work conceptually but Aurora Backtrack is the purpose-built recovery tool for this scenario.' } },
  { id: 'd2-rds-018', domain: 2, topics: ['RDS', 'security', 'SSL TLS'], type: 'single', stem: 'Database traffic between the application and RDS must be encrypted in transit. How is this enforced?', options: [{ id: 'A', text: 'RDS encrypts all traffic in transit automatically — no configuration needed' }, { id: 'B', text: 'Use SSL/TLS with the appropriate RDS CA certificate bundle — enforce SSL in the application connection string' }, { id: 'C', text: 'Enable VPC encryption — all traffic within the VPC is encrypted automatically' }, { id: 'D', text: 'Deploy RDS in a private subnet — private subnets encrypt all database traffic' }], correct: ['B'], explanation: 'RDS supports SSL/TLS for in-transit encryption. Download the RDS CA certificate, configure the connection string to require SSL. Use parameter group setting (require_secure_transport for MySQL) to enforce SSL server-side.', distractors: { A: 'RDS SSL is optional by default — it must be configured at the application level and enforced via parameter settings.', C: 'VPC does not encrypt traffic at the application layer — SSL/TLS is required for application-level encryption.', D: 'Private subnets isolate network access — they do not encrypt traffic.' } },
  { id: 'd2-rds-019', domain: 2, topics: ['Aurora', 'Aurora PostgreSQL', 'performance'], type: 'single', stem: 'An Aurora PostgreSQL writer instance is CPU-bound during peak hours. How can Aurora scale out read queries from the writer?', options: [{ id: 'A', text: 'Enable Aurora Serverless — it auto-scales the writer ACUs' }, { id: 'B', text: 'Add Aurora reader instances and point read queries to the reader endpoint' }, { id: 'C', text: 'Enable Aurora Parallel Query — splits queries across multiple instances automatically' }, { id: 'D', text: 'Use Aurora Global Database — the secondary region handles all read queries' }], correct: ['B'], explanation: 'Adding reader instances to the Aurora cluster offloads read queries from the writer. Applications use the reader endpoint (load-balanced across readers) for SELECT queries. Writer handles only writes, reducing CPU load.', distractors: { A: 'Aurora Serverless scales the writer capacity in ACU units — it does not separate reads from writes.', C: 'Aurora Parallel Query pushes processing to the storage layer for a single query — it does not offload queries to separate instances.', D: 'Aurora Global Database secondary regions can serve reads — but reader instances in the same cluster are simpler and lower latency.' } },
  { id: 'd2-rds-020', domain: 2, topics: ['RDS', 'snapshot', 'restore'], type: 'single', stem: 'An RDS snapshot must be shared with another AWS account. What is the limitation?', options: [{ id: 'A', text: 'Snapshots cannot be shared between accounts — they must be copied first' }, { id: 'B', text: 'Encrypted snapshots must use a customer-managed KMS key (not AWS managed key) for cross-account sharing' }, { id: 'C', text: 'Snapshots can only be shared within the same AWS Organization, not externally' }, { id: 'D', text: 'Shared snapshots are read-only — the receiving account must copy before use' }], correct: ['B'], explanation: 'RDS snapshot sharing limitation: snapshots encrypted with the AWS managed key (aws/rds) cannot be shared. Use a customer-managed KMS key, share both the snapshot and key access with the target account.', distractors: { A: 'Snapshots can be shared directly without copying — the KMS key type is the limiting factor for encrypted snapshots.', C: 'Snapshots can be shared with any AWS account ID — not limited to the same Organization.', D: 'Shared snapshots can be used directly — the receiving account does not need to copy them first.' } },
  { id: 'd2-rds-021', domain: 2, topics: ['Aurora', 'zero-downtime patching'], type: 'single', stem: 'Aurora maintenance patching requires a database restart. How does Aurora minimize downtime?', options: [{ id: 'A', text: 'Aurora stores connection state in memory so reconnections are instantaneous after restart' }, { id: 'B', text: 'Zero Downtime Patching (ZDP) — applies patches to the storage subsystem without restarting compute; connections preserved' }, { id: 'C', text: 'Aurora uses a rolling restart — readers restart first, then the writer, with no availability gap' }, { id: 'D', text: 'Aurora requires manual planned maintenance — no automated patching mechanism exists' }], correct: ['B'], explanation: 'Aurora MySQL supports Zero Downtime Patching — patches are applied to the Aurora storage subsystem while the database engine continues running. Application connections are briefly paused (not dropped) during patch application.', distractors: { A: 'Connection state is not stored between restarts — ZDP minimizes downtime by avoiding full restarts.', C: 'Rolling restarts happen for version upgrades, not for ZDP — ZDP is applied inline without instance restart.', D: 'Aurora has automated patching during maintenance windows — ZDP is one mechanism that minimizes the disruption.' } },
  { id: 'd2-rds-022', domain: 2, topics: ['RDS', 'monitoring', 'Performance Insights'], type: 'single', stem: 'A DBA wants to identify the exact SQL queries consuming the most database CPU. Tool?', options: [{ id: 'A', text: 'CloudWatch metrics — CPU utilization and query throughput per second' }, { id: 'B', text: 'RDS Performance Insights — visualizes database load by SQL query, wait events, and users' }, { id: 'C', text: 'Enhanced Monitoring — provides OS-level CPU metrics with 1-second granularity' }, { id: 'D', text: 'AWS Trusted Advisor — identifies performance bottlenecks in RDS instances' }], correct: ['B'], explanation: 'RDS Performance Insights shows database load (DB Load) broken down by SQL queries, wait events, users, and hosts. Pinpoints exactly which query is consuming the most database CPU or causing wait events.', distractors: { A: 'CloudWatch shows aggregate CPU metrics — not per-query breakdown. Performance Insights identifies specific queries.', C: 'Enhanced Monitoring provides OS-level metrics — not SQL query-level analysis.', D: 'Trusted Advisor provides general recommendations — not query-level performance analysis.' } },
  { id: 'd2-rds-023', domain: 2, topics: ['RDS', 'deletion protection'], type: 'single', stem: 'How do you prevent accidental deletion of an RDS production database?', options: [{ id: 'A', text: 'Enable automated backups — backups prevent deletion until retention period expires' }, { id: 'B', text: 'Enable RDS deletion protection — prevents deletion via API, CLI, or console until explicitly disabled' }, { id: 'C', text: 'Use AWS Config to detect and alert on deletion attempts before they complete' }, { id: 'D', text: 'Create an IAM deny policy for rds:DeleteDBInstance for all IAM users' }], correct: ['B'], explanation: 'RDS deletion protection: when enabled, any attempt to delete the instance returns an error. Must be disabled before deletion can proceed — provides a guardrail against accidental production database deletion.', distractors: { A: 'Automated backups do not prevent deletion — they are removed when the instance is deleted (unless final snapshot is taken).', C: 'AWS Config detects changes after they occur — deletion protection prevents the deletion from occurring.', D: 'IAM deny policies work but are harder to manage across multiple principals — deletion protection is an instance-level setting.' } },
  { id: 'd2-rds-024', domain: 2, topics: ['Aurora', 'cloning'], type: 'single', stem: 'A dev team needs a full copy of the production Aurora database for testing without a lengthy restore process. Option?', options: [{ id: 'A', text: 'Restore from the latest automated snapshot to a new Aurora cluster' }, { id: 'B', text: 'Aurora Fast Clone — creates a clone instantly using copy-on-write; only changed pages are copied' }, { id: 'C', text: 'Use Aurora Global Database — the secondary region automatically creates a copy of the primary' }, { id: 'D', text: 'Export to S3 using select-into-outfile and import to the dev database' }], correct: ['B'], explanation: 'Aurora Fast Cloning uses copy-on-write storage — the clone shares the same storage pages until one is modified. Creates a full logical copy in seconds or minutes regardless of database size. Cost-effective for dev/test.', distractors: { A: 'Snapshot restore creates a full copy but requires time proportional to data size — Fast Clone is nearly instantaneous.', C: 'Aurora Global Database is for cross-region DR/read scaling — not for creating dev/test clones.', D: 'S3 export and import is slow for large databases — Fast Clone is orders of magnitude faster.' } },
  { id: 'd2-rds-025', domain: 2, topics: ['RDS', 'VPC', 'subnet groups'], type: 'single', stem: 'An RDS instance must span multiple AZs for Multi-AZ. What network configuration is required?', options: [{ id: 'A', text: 'The RDS instance must have a public subnet for Multi-AZ standby communication' }, { id: 'B', text: 'Create a DB Subnet Group with subnets in at least 2 different AZs' }, { id: 'C', text: 'Multi-AZ only requires one subnet — AWS places the standby in a separate AZ automatically' }, { id: 'D', text: 'Enable VPC Multi-AZ routing — this prepares the VPC for RDS Multi-AZ deployments' }], correct: ['B'], explanation: 'RDS requires a DB Subnet Group with subnets in at least 2 AZs. For Multi-AZ, the primary is in one AZ subnet and the standby in another AZ subnet — both must be included in the subnet group.', distractors: { A: 'RDS does not require public subnets — private subnets are preferred and recommended for security.', C: 'AWS cannot place the standby in any AZ if only one subnet is specified — a multi-AZ subnet group is required.', D: 'There is no VPC Multi-AZ routing setting — the DB Subnet Group is the required configuration.' } },
  { id: 'd2-rds-026', domain: 2, topics: ['RDS', 'Multi-AZ', 'scaling limitations'], type: 'single', stem: 'An RDS Multi-AZ standby receives writes through synchronous replication. Can it serve read queries?', options: [{ id: 'A', text: 'Yes — Multi-AZ standby can serve read queries through the reader endpoint' }, { id: 'B', text: 'No — Multi-AZ standby is for failover only; it does not serve any read traffic' }, { id: 'C', text: 'Yes — but only for read replicas created from the Multi-AZ pair' }, { id: 'D', text: 'Yes — through Multi-AZ reader mode, enabled in the RDS console' }], correct: ['B'], explanation: 'RDS Multi-AZ standby is a hot standby for failover only — it does not serve read traffic. For read scaling, create separate Read Replicas. Aurora Multi-AZ reader instances do serve reads (different product).', distractors: { A: 'The reader endpoint is for Read Replicas — not the Multi-AZ standby.', C: 'Read replicas are separate from Multi-AZ — they are not created from the standby.', D: 'There is no Multi-AZ reader mode for standard RDS — this is an Aurora-specific concept.' } },
  { id: 'd2-rds-027', domain: 2, topics: ['Aurora', 'write forwarding'], type: 'single', stem: 'An application connects to an Aurora Global Database secondary region reader endpoint and sends a write. What happens with write forwarding enabled?', options: [{ id: 'A', text: 'The write fails with an error — secondary regions are read-only' }, { id: 'B', text: 'The write is forwarded to the primary region writer transparently; the secondary reader becomes consistent' }, { id: 'C', text: 'The write is queued in the secondary region and applied after a replication event' }, { id: 'D', text: 'Aurora splits the write between both regions simultaneously' }], correct: ['B'], explanation: 'Aurora Global Database write forwarding: writes sent to secondary region reader endpoints are transparently forwarded to the primary region writer. Applications in the secondary region can use a single endpoint for reads and writes.', distractors: { A: 'Without write forwarding, writes to the secondary fail — with write forwarding enabled, they are forwarded to primary.', C: 'Writes are forwarded to the primary in real-time — there is no local secondary queue.', D: 'Aurora Global Database has one writer in the primary region — writes are not split across regions.' } },
  { id: 'd2-rds-028', domain: 2, topics: ['RDS', 'secret rotation', 'proxy'], type: 'single', stem: 'RDS Proxy is used with Secrets Manager rotation. What happens to existing connections during password rotation?', options: [{ id: 'A', text: 'Existing connections are dropped when the password changes — applications must reconnect' }, { id: 'B', text: 'RDS Proxy maintains existing connections using the old credentials while transparently switching to new ones' }, { id: 'C', text: 'Rotation is blocked while Proxy has active connections — Proxy waits for connections to close' }, { id: 'D', text: 'All connections are paused for 30 seconds while Proxy updates to the new credentials' }], correct: ['B'], explanation: 'RDS Proxy integrates with Secrets Manager rotation. During rotation, existing connections remain active using cached credentials. New connections use the new credentials. Zero application impact during rotation.', distractors: { A: 'RDS Proxy specifically prevents connection drops during rotation — this is one of its key features.', C: 'Rotation does not wait for connections — Proxy handles the credential transition seamlessly.', D: 'There is no 30-second pause — RDS Proxy provides continuous connection availability during rotation.' } },
  { id: 'd2-rds-029', domain: 2, topics: ['RDS', 'cost', 'reserved instances'], type: 'single', stem: 'An RDS instance runs 24/7 and the instance type will not change for 1 year. How to reduce cost by up to 40%?', options: [{ id: 'A', text: 'Convert to Aurora Serverless to eliminate idle charges' }, { id: 'B', text: 'Purchase a 1-year Reserved DB Instance — up to 40% discount for No Upfront or Partial Upfront' }, { id: 'C', text: 'Enable RDS Multi-AZ — Multi-AZ instances have lower hourly rates' }, { id: 'D', text: 'Use Savings Plans — Compute Savings Plans cover RDS at the same discount rate as EC2' }], correct: ['B'], explanation: 'RDS Reserved Instances: 1-year or 3-year commitment with No Upfront (~40% off), Partial Upfront, or All Upfront (~60% off). For stable workloads, Reserved is the direct cost reduction mechanism.', distractors: { A: 'Aurora Serverless charges by ACU-second — for 24/7 consistent load, provisioned Reserved is often cheaper.', C: 'Multi-AZ increases cost (charges for standby) — it does not reduce the primary instance hourly rate.', D: 'Compute Savings Plans apply to EC2, Lambda, and Fargate — not to RDS. RDS uses Reserved Instances.' } },
  { id: 'd2-rds-030', domain: 2, topics: ['Aurora', 'Parallel Query'], type: 'single', stem: 'A large analytics query on Aurora MySQL scans hundreds of millions of rows. How does Parallel Query help?', options: [{ id: 'A', text: 'Splits the query across multiple Aurora instances for parallel processing' }, { id: 'B', text: 'Pushes query processing down to the storage layer where data already lives, reducing I/O to the head node' }, { id: 'C', text: 'Caches query results in ElastiCache to avoid repeated full scans' }, { id: 'D', text: 'Automatically partitions the table into smaller chunks for faster sequential scanning' }], correct: ['B'], explanation: 'Aurora Parallel Query pushes filter, projection, and aggregation processing to the distributed storage layer. Only matching rows are sent to the head node — dramatically reduces I/O for analytical queries.', distractors: { A: 'Parallel Query does not distribute across multiple Aurora instances — processing happens within the storage subsystem.', C: 'Parallel Query does not use ElastiCache — it optimizes the query by processing in the storage layer.', D: 'Partitioning is a separate DDL operation — Parallel Query works on existing tables without schema changes.' } },
  { id: 'd2-rds-031', domain: 2, topics: ['RDS', 'exports to S3'], type: 'single', stem: 'RDS data must be exported to S3 for machine learning model training. Fastest method for large datasets?', options: [{ id: 'A', text: 'SELECT INTO OUTFILE on the RDS instance — exports directly to S3 from the engine' }, { id: 'B', text: 'RDS Snapshot Export to S3 — exports in Apache Parquet format, parallelized, stored in S3' }, { id: 'C', text: 'AWS DMS continuous replication to S3 — exports data to S3 in near-real-time' }, { id: 'D', text: 'AWS Glue ETL job reads from RDS and writes to S3 in the required format' }], correct: ['B'], explanation: 'RDS Snapshot Export to S3: exports the full snapshot in Parquet format directly to S3. Parallelized export process. Fast for large datasets. Parquet is efficient for ML model training and analytical workloads.', distractors: { A: 'SELECT INTO OUTFILE S3 only works for Aurora MySQL — not all RDS engines.', C: 'DMS continuous replication is for migration/CDC — not bulk data export for ML training.', D: 'Glue ETL reads live from RDS — adds query load to production and is slower than snapshot export.' } },
  { id: 'd2-rds-032', domain: 2, topics: ['RDS', 'scaling vertically'], type: 'single', stem: 'An RDS instance needs to scale from db.t3.medium to db.r5.2xlarge. What is the impact?', options: [{ id: 'A', text: 'No downtime — RDS scales vertically online without any service interruption' }, { id: 'B', text: 'Brief downtime required — Multi-AZ reduces this; instance restarts on the new hardware' }, { id: 'C', text: 'A new instance is launched and old one is terminated after data migration completes' }, { id: 'D', text: 'Vertical scaling requires creating a read replica of the desired size and promoting it' }], correct: ['B'], explanation: 'RDS vertical scaling (resize) requires a brief instance restart on new hardware. With Multi-AZ, the standby is upgraded first, then failover occurs — minimizes downtime to the failover period (~1-2 minutes).', distractors: { A: 'Online vertical scaling without restart is not possible for standard RDS — Aurora has a more graceful scaling mechanism.', C: 'RDS does not launch a separate instance and migrate data — the existing instance is resized in place with a restart.', D: 'Read replica promotion is for horizontal read scaling — vertical scaling uses modify instance type directly.' } },
  { id: 'd2-rds-033', domain: 2, topics: ['Aurora', 'machine learning integration'], type: 'single', stem: 'Aurora SQL queries need to call SageMaker models for inference directly from SQL. How?', options: [{ id: 'A', text: 'This requires exporting data to S3 first — Aurora cannot call ML services directly from SQL' }, { id: 'B', text: 'Aurora Machine Learning — built-in SQL functions call SageMaker or Comprehend from within queries' }, { id: 'C', text: 'Use Lambda integration from Aurora — call a Lambda function that invokes SageMaker' }, { id: 'D', text: 'Aurora ML requires a special ML instance type — not available on standard Aurora instances' }], correct: ['B'], explanation: 'Aurora Machine Learning integrates Aurora directly with SageMaker and Comprehend. SQL functions like aws_sagemaker_invoke_endpoint() call ML models inline in queries — no data export needed.', distractors: { A: 'Aurora ML calls SageMaker directly from SQL — no S3 export is required.', C: 'Lambda integration is a separate capability — Aurora ML has direct SageMaker integration without Lambda.', D: 'Aurora ML works on standard Aurora instances — no special ML instance type is required.' } },
  { id: 'd2-rds-034', domain: 2, topics: ['RDS', 'event subscriptions'], type: 'single', stem: 'Operations team needs email notification when RDS failover occurs. Configuration?', options: [{ id: 'A', text: 'Enable RDS Enhanced Monitoring — sends email alerts on failover events' }, { id: 'B', text: 'Create an RDS Event Subscription for the DB instance targeting an SNS topic with email subscribers' }, { id: 'C', text: 'Set up a CloudWatch alarm on the RDS FreeStorageSpace metric to trigger on failover' }, { id: 'D', text: 'Configure AWS Health Dashboard notifications for RDS maintenance events' }], correct: ['B'], explanation: 'RDS Event Subscriptions: subscribe to specific RDS event categories (availability, failover, maintenance) for a specific DB instance. Events are published to an SNS topic — add email subscribers for notifications.', distractors: { A: 'Enhanced Monitoring provides OS metrics — it does not send alerts for RDS events like failover.', C: 'FreeStorageSpace measures disk — it does not indicate failover. RDS Event Subscription is the right mechanism.', D: 'AWS Health covers AWS-initiated maintenance — RDS Event Subscriptions cover database-level events including failover.' } },
  { id: 'd2-rds-035', domain: 2, topics: ['RDS', 'snapshot sharing', 'copy'], type: 'single', stem: 'An RDS snapshot needs to be available in a different AWS region for DR. How?', options: [{ id: 'A', text: 'Snapshots are automatically replicated across all regions — no action needed' }, { id: 'B', text: 'Copy the snapshot to the target region — CopyDBSnapshot API or console copy operation' }, { id: 'C', text: 'Share the snapshot with the target region account ID — sharing enables cross-region access' }, { id: 'D', text: 'Enable cross-region backup in the RDS settings — automated cross-region copies are configured there' }], correct: ['B'], explanation: 'RDS snapshots are regional by default. Use CopyDBSnapshot to copy to another region. You can automate this with EventBridge rules that trigger Lambda on snapshot creation.', distractors: { A: 'Snapshots are not automatically replicated — explicit copy operations are required.', C: 'Snapshot sharing is cross-account within the same region — it does not enable cross-region access.', D: 'There is no built-in cross-region backup setting in standard RDS — AWS Backup can automate cross-region copies.' } },
  { id: 'd2-rds-036', domain: 2, topics: ['Aurora', 'Global Database', 'failover RTO'], type: 'single', stem: 'An Aurora Global Database has a primary in us-east-1 and secondary in eu-west-1. How is a regional failover performed?', options: [{ id: 'A', text: 'Aurora automatically promotes the secondary when it detects primary region failure' }, { id: 'B', text: 'Manually initiate a managed failover or detach the secondary and promote it as the new primary' }, { id: 'C', text: 'Create a new Aurora cluster in eu-west-1 from the latest automated backup' }, { id: 'D', text: 'Update Route 53 records to point to the secondary region after it self-promotes' }], correct: ['B'], explanation: 'Aurora Global Database failover is manual (not automatic for full region failures). Perform a managed planned failover (promotes secondary, primary becomes secondary) or remove and promote in ~1 minute.', distractors: { A: 'Aurora Global Database does not auto-promote on regional failure — manual action is required for cross-region failover.', C: 'Restoring from backup takes longer than promoting the existing secondary — secondary promotion is minutes, not hours.', D: 'Route 53 is updated after promotion — but the promotion itself is the manual step, not a DNS update.' } },
  { id: 'd2-rds-037', domain: 2, topics: ['RDS', 'PITR', 'restore'], type: 'single', stem: 'RDS PITR is used to restore to a specific point. What is the restored database state?', options: [{ id: 'A', text: 'The exact state at the specified time — all transactions committed before that time are included' }, { id: 'B', text: 'The nearest automated snapshot before the target time — exact PITR is approximate' }, { id: 'C', text: 'A new RDS instance is created; the original instance is deleted automatically' }, { id: 'D', text: 'PITR restores to a 5-minute-granular point — exact second is not supported' }], correct: ['A'], explanation: 'RDS PITR uses automated backups + transaction logs to restore to any second within the retention period. The restored state includes all committed transactions up to the exact specified time.', distractors: { B: 'PITR is not limited to snapshot points — transaction logs enable second-level precision between snapshots.', C: 'PITR creates a new RDS instance — the original instance is NOT deleted. Both instances run until you delete one.', D: 'PITR supports second-level precision — not just 5-minute granularity.' } },
  { id: 'd2-rds-038', domain: 2, topics: ['Aurora', 'storage scaling automatic'], type: 'single', stem: 'Aurora storage scaling behavior compared to standard RDS — what is different?', options: [{ id: 'A', text: 'Aurora requires manual storage allocation like RDS — no automatic scaling' }, { id: 'B', text: 'Aurora storage grows automatically in 10 GB increments up to 128 TiB — no manual allocation' }, { id: 'C', text: 'Aurora storage scales automatically but requires enabling Storage Autoscaling in the console' }, { id: 'D', text: 'Aurora storage is unlimited — no maximum size limitation exists' }], correct: ['B'], explanation: 'Aurora manages storage automatically — it grows in 10 GB increments as data increases, up to 128 TiB. No pre-provisioning, no storage limit configuration, no autoscaling setting required. This is automatic.', distractors: { A: 'Aurora automatically manages storage — no manual allocation is needed unlike standard RDS.', C: 'Aurora storage scaling is automatic by default — no console setting needs to be enabled.', D: 'Aurora maximum storage is 128 TiB — there is a maximum size limit.' } },
  { id: 'd2-rds-039', domain: 2, topics: ['RDS', 'Blue Green deployments'], type: 'single', stem: 'A major schema migration is needed on a production RDS database with minimum downtime. Approach?', options: [{ id: 'A', text: 'Run the migration during a maintenance window — accept several minutes of downtime' }, { id: 'B', text: 'RDS Blue/Green Deployments — create a green copy with the migration applied, then switch over with <1 minute downtime' }, { id: 'C', text: 'Use AWS DMS with change data capture to migrate the schema with minimal downtime' }, { id: 'D', text: 'Use Aurora Backtrack to rollback if the migration fails — reduces risk of extended downtime' }], correct: ['B'], explanation: 'RDS Blue/Green Deployments: provision a green environment (replica of blue), apply schema changes on green, verify, then switch traffic in <1 minute. Quick rollback by switching back to blue if issues arise.', distractors: { A: 'Maintenance windows accept downtime — Blue/Green keeps downtime under 1 minute.', C: 'DMS is for data migration between different database engines — Blue/Green is for same-engine in-place schema changes.', D: 'Backtrack reverts to before the migration on the same cluster — Blue/Green keeps both environments until verified.' } },
  { id: 'd2-rds-040', domain: 2, topics: ['RDS', 'Multi-AZ vs Read Replica'], type: 'multi', stem: 'Which TWO statements correctly distinguish RDS Multi-AZ from Read Replicas?', options: [{ id: 'A', text: 'Multi-AZ uses synchronous replication; Read Replicas use asynchronous replication' }, { id: 'B', text: 'Multi-AZ standby can serve read traffic; Read Replicas cannot' }, { id: 'C', text: 'Multi-AZ provides automatic failover; Read Replicas require manual promotion' }, { id: 'D', text: 'Multi-AZ and Read Replicas both use synchronous replication for data consistency' }], correct: ['A', 'C'], explanation: 'Multi-AZ: synchronous replication, automatic failover, standby not readable. Read Replicas: asynchronous replication, must be manually promoted on failure, readable.', distractors: { B: 'Multi-AZ standby is NOT readable — only Aurora reader instances serve reads. Read Replicas ARE readable.', D: 'Read Replicas use asynchronous replication — Multi-AZ is the one with synchronous replication.' } },
  { id: 'd2-rds-041', domain: 2, topics: ['Aurora', 'Auto Scaling readers'], type: 'single', stem: 'Aurora has 1 reader. Traffic spikes cause the reader to become overloaded. How to add readers automatically?', options: [{ id: 'A', text: 'Configure Aurora Storage Autoscaling — it adds readers when storage is under pressure' }, { id: 'B', text: 'Aurora Auto Scaling — adds and removes reader instances based on a CloudWatch metric target' }, { id: 'C', text: 'Create an Auto Scaling group for Aurora readers — specify min, max, and desired reader count' }, { id: 'D', text: 'Aurora automatically adds readers at 80% CPU — no configuration needed' }], correct: ['B'], explanation: 'Aurora Auto Scaling for read replicas: define a scaling policy with a target metric (CPUUtilization, connections per instance). Aurora adds/removes readers up to the configured maximum to maintain the target.', distractors: { A: 'Storage Autoscaling increases storage capacity — it does not add reader instances.', C: 'EC2 Auto Scaling Groups are for EC2 instances — Aurora readers are managed by Aurora Auto Scaling, not ASG.', D: 'Aurora does not automatically add readers without Auto Scaling configured — it requires explicit policy setup.' } },
  { id: 'd2-rds-042', domain: 2, topics: ['RDS', 'connection limits'], type: 'single', stem: 'RDS MySQL has a max_connections limit based on instance size. The application is hitting this limit. Solutions?', options: [{ id: 'A', text: 'Increase max_connections in the parameter group — the limit is a soft cap that can be raised to any value' }, { id: 'B', text: 'Use RDS Proxy to pool connections; OR scale up the instance size to increase the max_connections limit' }, { id: 'C', text: 'Add read replicas — each replica has its own separate connection limit doubling total capacity' }, { id: 'D', text: 'Enable connection multiplexing in the RDS console — aggregates connections at the RDS layer' }], correct: ['B'], explanation: 'Two solutions: (1) RDS Proxy pools connections — many app connections share fewer DB connections; (2) Larger instance size increases max_connections (proportional to RAM). Parameter group change alone is limited by available memory.', distractors: { A: 'max_connections is memory-limited — raising it beyond what the instance RAM supports causes instability.', C: 'Read replicas have separate connection limits but only for reads — write connection limit is still the primary bottleneck.', D: 'Connection multiplexing in the RDS console does not exist as a setting — RDS Proxy is the multiplexing mechanism.' } },
  { id: 'd2-rds-043', domain: 2, topics: ['RDS', 'tagging', 'billing'], type: 'single', stem: 'RDS costs must be allocated to individual teams based on their database instances. How?', options: [{ id: 'A', text: 'Create separate AWS accounts per team — account-level billing separates costs automatically' }, { id: 'B', text: 'Tag RDS instances with Team name; enable cost allocation tags in Billing; filter Cost Explorer by tag' }, { id: 'C', text: 'Use separate VPCs per team — VPC-level billing groups costs by VPC' }, { id: 'D', text: 'AWS Cost Categories automatically groups RDS costs by the creator\'s IAM identity' }], correct: ['B'], explanation: 'RDS instance tagging + cost allocation tags: tag instances with Team=engineering, Team=data, etc. Enable these tags in AWS Cost Management. Cost Explorer breaks down RDS costs by tag value per team.', distractors: { A: 'Separate accounts work but add management overhead — tagging achieves team-level allocation within one account.', C: 'VPC-level billing does not exist — Cost Explorer does not group costs by VPC automatically.', D: 'Cost Categories can be configured manually — but they do not automatically group by IAM creator identity.' } },
  { id: 'd2-rds-044', domain: 2, topics: ['Aurora', 'endpoints', 'custom'], type: 'single', stem: 'An Aurora cluster has 2 small readers (r5.large) and 1 large reader (r5.4xlarge) for analytics. How to route analytics queries only to the large reader?', options: [{ id: 'A', text: 'Use the reader endpoint — Aurora load-balances to the large reader automatically for heavy queries' }, { id: 'B', text: 'Create a custom endpoint containing only the r5.4xlarge instance — point analytics queries to it' }, { id: 'C', text: 'Use instance endpoints — connect directly to the r5.4xlarge instance by its hostname' }, { id: 'D', text: 'Tag the r5.4xlarge instance as analytics — Aurora routes heavy queries to tagged instances' }], correct: ['B'], explanation: 'Aurora custom endpoints: create a named endpoint containing a specific subset of instances. Analytics queries use the custom endpoint → only the large r5.4xlarge instance serves them. Reader endpoint handles OLTP traffic.', distractors: { A: 'Reader endpoint load-balances across all readers — analytics queries could hit small instances.', C: 'Instance endpoints connect to a specific instance — custom endpoints are preferred over instance endpoints for availability.', D: 'Aurora does not support query-routing by instance tags — custom endpoints are the explicit routing mechanism.' } },
  { id: 'd2-rds-045', domain: 2, topics: ['RDS', 'audit logging'], type: 'single', stem: 'All SQL queries executed against an RDS PostgreSQL instance must be logged for compliance. How?', options: [{ id: 'A', text: 'Enable CloudTrail data events for RDS — captures all SQL query content' }, { id: 'B', text: 'Enable pgaudit extension via parameter group; publish PostgreSQL logs to CloudWatch Logs' }, { id: 'C', text: 'Enable Enhanced Monitoring — captures all SQL queries with 1-second granularity' }, { id: 'D', text: 'RDS Performance Insights captures all queries — export to S3 for compliance reporting' }], correct: ['B'], explanation: 'pgaudit extension provides detailed audit logging for PostgreSQL — logs DML, DDL, and connection events. Enable via RDS parameter group, then publish PostgreSQL logs to CloudWatch Logs for retention and analysis.', distractors: { A: 'CloudTrail captures RDS API calls (CreateDBInstance, etc.) — not SQL query content.', C: 'Enhanced Monitoring provides OS and process metrics — not SQL query audit logs.', D: 'Performance Insights captures query metrics (statistics) — not a legal audit trail with user and timestamp per query.' } },
]
